function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

const invRows = inv.filter(function (r) { return nz(r.investor).indexOf('kaecapital') >= 0; })
  .map(function (r) { return { row: r.row_number, investor: s(r.investor), email: s(r.email),
    do_not_contact: s(r.do_not_contact), sector: s(r.sector), stage: s(r.stage), cheque: s(r.cheque_inr_cr) }; });

const rows = pipe.filter(function (p) { return nz(p.investor).indexOf('kaecapital') >= 0; });
const buckets = { sent_pending_fu: [], sent_closed: [], never_sent: [], paused: [] };
for (const p of rows) {
  const rec = { row: p.row_number, deal_id: s(p.deal_id), startup: s(p.startup),
    shared: s(p.deal_shared), resp: s(p.investor_response), pause: s(p.pause),
    next_action: s(p.next_action), next_due: s(p.next_due) };
  if (s(p.pause).toLowerCase() === 'yes') { buckets.paused.push(rec); continue; }
  if (s(p.deal_shared).toLowerCase() !== 'yes') { buckets.never_sent.push(rec); continue; }
  const r = s(p.investor_response).toLowerCase();
  if (r === 'pass' || r === 'passed') { buckets.sent_closed.push(rec); } else { buckets.sent_pending_fu.push(rec); }
}
return [{ json: { investor_rows: invRows, total_pipeline_rows: rows.length,
  counts: { never_sent: buckets.never_sent.length, sent_pending_fu: buckets.sent_pending_fu.length,
    sent_closed: buckets.sent_closed.length, already_paused: buckets.paused.length },
  never_sent: buckets.never_sent, sent_pending_fu: buckets.sent_pending_fu,
  already_paused: buckets.paused.slice(0, 5) } }];
